function showCardDetail(registr){const c=dedupCardDB.find(x=>x.registr===registr);if(!c){toast('未找到报告卡'+registr);return}const ageCalc=c.birthda?Math.floor((new Date()-new Date(c.birthda))/(365.25*24*3600*1000))+'岁':'-';const sections=[{title:'发病人口信息',fields:[['登记编号',c.registr],['记录类型',c.reco],['姓名',c.name],['其他证件',c.idtype],['身份证号',c.indno],['性别',c.sex],['出生日期',c.birthda],['年龄',ageCalc],['联系电话',c.phone],['联系人关系',c.cprel],['联系人',c.cperson],['联系人电话',c.cphone],['民族',c.trib],['婚姻状况',c.mari],['职业',c.occu],['工作单位',c.workcom],['户籍地址',c.address],['户籍详细地址',c.addressdet],['常住地址',c.conservation],['常住详细地址',c.consdet]]},{title:'肿瘤报告信息',fields:[['发病部位',c.topo],['亚部位',c.subtopo],['病理类型',c.morp],['行为',c.beha],['分级',c.grad],['诊断依据',c.basi],['临床分期',c.stage],['TNM分期',c.tnm],['确诊日期',c.inciden],['ICD10',c.icd10],['治疗信息',c.treaInfo],['诊断结果',c.diagnosisResult],['详细诊断结果',c.detailedDiagnosisResult],['住院号',c.hosp],['门诊号',c.caseno],['报告日期',c.reportd],['报告医师',c.repDoct]]},{title:'随访报告信息',fields:[['最后接触日期',c.dlc],['最后接触状态',c.state],['生存月数',c.surmonth],['死亡地点',c.deadplace],['根本死因',c.caus],['死因ICD10编码',c.causicd],['死亡日期',c.deathda],['死亡报告医师',c.deadDoct]]}];const html=sections.map(s=>'<div style="margin-bottom:20px"><div style="font-weight:600;font-size:14px;color:#334155;margin-bottom:10px;padding-bottom:6px;border-bottom:2px solid #e2e8f0">'+s.title+'</div><div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px 32px">'+s.fields.map(f=>'<div style="display:flex;gap:8px;align-items:baseline"><span style="color:#94a3b8;min-width:110px;font-size:13px;flex-shrink:0">'+f[0]+'</span><span style="color:#1f2937;font-size:13px;font-weight:500">'+(f[1]||'-')+'</span></div>').join('')+'</div></div>').join('');const overlay=document.createElement('div');overlay.className='cd-overlay';overlay.style.zIndex='10000';overlay.innerHTML='<div class="cd-dialog" style="max-width:720px"><div class="cd-header"><span>报告卡详情 - '+c.registr+'</span><span class="cd-close" onclick="this.closest(\'.cd-overlay\').remove()">×</span></div><div class="cd-body" style="padding:20px 24px;max-height:70vh;overflow-y:auto">'+html+'</div><div class="cd-header" style="border-top:1px solid #e2e8f0;border-bottom:none;justify-content:flex-end;gap:8px"><button class="btn btn-ghost btn-sm" onclick="this.closest(\'.cd-overlay\').remove()">关闭</button></div></div>';overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.remove()});document.body.appendChild(overlay)}
function renderDedupPage(){const s=dedupState.subId;if(s==='quality-dup-card')return renderDedupCard();if(s==='quality-dup-multi')return renderDedupMulti();if(s==='quality-dup-pop')return renderDedupPop();if(s==='quality-dup-param')return renderDedupParam();if(s==='quality-dup-field')return renderDedupField();return '<div class="panel"><div class="panel-body"><div class="empty-state">页面开发中</div></div></div>'}

