function dedupCmpReset(){const overlay=document.querySelector('.cd-overlay[style*="z-index: 10000"],.cd-overlay[style*="z-index:10000"]');if(!overlay)return;overlay.querySelectorAll('.dedup-cmp-cell').forEach(cell=>{dedupCmpUnhighlightCell(cell);cell.style.opacity='';cell.style.pointerEvents=''});overlay.querySelectorAll('.dedup-cmp-col-check').forEach(cb=>{cb.checked=true});const cards=[{registr:'JX20240001'},{registr:'JX20240002'},{registr:'JX20240003'}];overlay.querySelectorAll('.dedup-cmp-cell').forEach(cell=>{const field=cell.dataset.field;const idx=parseInt(cell.dataset.idx);if(idx===0&&cell.textContent.replace(' ✓','')!=='-'){dedupCmpHighlightCell(cell)}})}
function dedupCmpCancel(){const overlays=document.querySelectorAll('.cd-overlay');overlays.forEach(o=>{if(o.style.zIndex==='10000'||o.style.zIndex==='')o.remove()})}
