function renderDedupParam(){
const st=dedupParamState;
const isCondition=st.type==='condition';
const typeLabel=isCondition?'查重条件':'字段组合';
const data=isCondition?dedupConditionData:dedupComboData;
const kw=(st.keyword||'').toLowerCase();
const filtered=kw?data.filter(r=>((r.name||'')+(r.id||'')).toLowerCase().includes(kw)):data;
const rows=filtered.map(r=>{
const name=isCondition?r.combos.map(c=>dedupComboName(c)).join(' '+r.logic+' '):r.name;
return '<tr>'+
'<td>'+r.id+'</td>'+
'<td style="text-align:left">'+name+'</td>'+
'<td>'+(r.status==='启用'?'<span class="badge badge-success">启用</span>':'<span class="badge badge-muted">禁用</span>')+'</td>'+
'<td>'+r.created+'</td>'+
'<td>'+r.modified+'</td>'+
'<td><button class="btn btn-primary btn-xs" onclick="dedupParamEdit(\''+r.id+'\')">编辑</button> <button class="btn btn-danger btn-xs" onclick="dedupParamDelete(\''+r.id+'\')">删除</button></td>'+
'</tr>'
}).join('');
const archBox='<div class="entry-alert"><div class="entry-alert-title">使用说明</div><ol>'+
'<li>选择类型可切换"字段组合"与"查重条件"两套参数。</li>'+
'<li>字段组合：从合并字段参数(2.3.6)选择字段，设置字段间"与/或"逻辑。</li>'+
'<li>查重条件：引用已定义的字段组合，设置组合间"与/或"逻辑。</li>'+
'<li>设置查重条件前须先设置字段组合；禁用的参数不参与查重。</li></ol></div>';
return '<div class="page-toolbar"><div class="page-toolbar-title"><span class="icon">●</span>自动查重参数</div></div>'+
archBox+
'<div class="panel"><div class="panel-body">'+
'<div class="filter-toolbar">'+
'<div class="form-group" style="min-width:160px"><label>选择类型</label><select onchange="dedupParamState.type=this.value;dedupParamState.keyword=\'\';renderPage(\'quality-dup-param\')"><option value="condition"'+(isCondition?' selected':'')+'>查重条件</option><option value="combo"'+(!isCondition?' selected':'')+'>字段组合</option></select></div>'+
'<div class="form-group search-group" style="max-width:240px"><label>关键字</label><input type="text" value="'+(st.keyword||'')+'" placeholder="参数名称 / 序号" oninput="dedupParamState.keyword=this.value"></div>'+
'<div class="filter-actions" style="margin-left:auto"><button class="btn btn-primary btn-sm" onclick="renderPage(\'quality-dup-param\')">查询</button><button class="btn btn-ghost btn-sm" onclick="dedupParamState.keyword=\'\';renderPage(\'quality-dup-param\')">重置</button><button class="btn btn-primary btn-sm" style="margin-left:8px" onclick="dedupParamAdd(\'condition\')">+ 添加查重条件</button><button class="btn btn-outline btn-sm" onclick="dedupParamAdd(\'combo\')">+ 添加字段组合</button></div>'+
'</div>'+
'<div style="margin-bottom:8px;color:#667085;font-size:13px">当前：<strong style="color:var(--primary)">'+typeLabel+'</strong>，共 '+filtered.length+' 条记录'+(isCondition?'（已启用 '+data.filter(r=>r.status==='启用').length+' 条）':'（已启用 '+data.filter(r=>r.status==='启用').length+' 条）')+'</div>'+
'<div class="table-wrap"><table class="data-table" style="min-width:820px"><thead><tr><th>序号</th><th>参数名称</th><th>使用状态</th><th>创建时间</th><th>修改时间</th><th>操作</th></tr></thead><tbody>'+rows+'</tbody></table></div>'+
'</div></div>'
}

function dedupParamAdd(formType){dedupParamState.editingId=null;dedupParamState.formType=formType;dedupParamOpenForm(false,null,formType)}
function dedupParamEdit(id){dedupParamState.editingId=id;dedupParamState.formType=dedupParamState.type;dedupParamOpenForm(true,id,dedupParamState.type)}
function dedupParamDelete(id){
const isCondition=dedupParamState.type==='condition';
const label=isCondition?'查重条件':'字段组合';
showConfirm('确认删除','确定要删除'+label+'「'+id+'」吗？删除后不可恢复。',()=>{toast('删除成功');renderPage('quality-dup-param')})
}

function dedupParamFieldChecklist(selected){
const groups=['基本信息','肿瘤报告信息','随访报告信息'];
return groups.map(g=>{
const fields=dedupFieldParamData.filter(f=>f.group===g);
const items=fields.map(f=>{
const checked=selected.includes(f.var)?'checked':'';
return '<label class="ms-check-item"><input type="checkbox" class="param-sel-check" value="'+f.var+'" '+checked+' onchange="dedupParamUpdateSelCount()"><span class="ms-item-name">'+f.name+'</span><span class="ms-item-var">'+f.var+'</span></label>'
}).join('');
return '<div class="ms-check-group"><div class="ms-check-group-title">'+g+'（'+fields.length+'个字段）</div>'+items+'</div>'
}).join('')
}
function dedupParamComboChecklist(selected){
if(dedupComboData.length===0)return '<div class="ms-check-item" style="color:#94a3b8;justify-content:center">暂无字段组合，请先切换到「字段组合」类型添加</div>';
return dedupComboData.map(c=>{
const checked=selected.includes(c.id)?'checked':'';
const tag=c.status==='启用'?'<span class="badge badge-success ms-item-tag">启用</span>':'<span class="badge badge-muted ms-item-tag">禁用</span>';
return '<label class="ms-check-item"><input type="checkbox" class="param-sel-check" value="'+c.id+'" '+checked+' onchange="dedupParamUpdateSelCount()"><span class="ms-item-name">'+c.name+'</span><span class="ms-item-var">('+c.id+')</span>'+tag+'</label>'
}).join('')
}
function dedupParamUpdateSelCount(){
const modal=document.getElementById('dedupParamModal');if(!modal)return;
const n=modal.querySelectorAll('.param-sel-check:checked').length;
const el=modal.querySelector('#paramSelCount');if(el)el.textContent='已选 '+n+' 项';
}

function dedupParamOpenForm(isEdit,id,formType){
const isCondition=formType==='condition';
const typeLabel=isCondition?'查重条件':'字段组合';
const data=isCondition?dedupConditionData:dedupComboData;
const r=isEdit?data.find(x=>x.id===id):null;
const selected=isCondition?(r?r.combos:[]):(r?r.fields:[]);
const logic=r?r.logic:'与';
const status=r?r.status:'启用';
const desc=r?r.desc:'';
const name=r?r.name:'';
let selBox;
if(isCondition){
selBox='<div class="sel-count-bar"><span>从已定义的字段组合中选择（可多选）</span><span id="paramSelCount">已选 '+selected.length+' 项</span></div><div class="ms-check-box" style="border-top-left-radius:0;border-top-right-radius:0">'+dedupParamComboChecklist(selected)+'</div>';
}else{
selBox='<div class="sel-count-bar"><span>从合并字段参数(2.3.6)中选择字段（可多选）</span><span id="paramSelCount">已选 '+selected.length+' 项</span></div><div class="ms-check-box" style="border-top-left-radius:0;border-top-right-radius:0">'+dedupParamFieldChecklist(selected)+'</div>';
}
const nameField=isCondition?'':'<div class="form-group"><label>组合名称 <span class="required">*</span></label><input type="text" id="paramName" value="'+name+'" placeholder="请输入组合名称" style="width:100%"></div>';
const formHtml=
'<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px 16px">'+
nameField+
'<div class="form-group"><label>逻辑类型 <span class="required">*</span></label><div class="radio-inline" style="padding-top:8px"><label><input type="radio" name="paramLogic" value="与" '+(logic==='与'?'checked':'')+'> 与（AND，全部匹配）</label><label><input type="radio" name="paramLogic" value="或" '+(logic==='或'?'checked':'')+'> 或（OR，任一匹配）</label></div></div>'+
'<div class="form-group"><label>使用状态</label><div class="radio-inline" style="padding-top:8px"><label><input type="radio" name="paramStatus" value="启用" '+(status==='启用'?'checked':'')+'> 启用</label><label><input type="radio" name="paramStatus" value="禁用" '+(status==='禁用'?'checked':'')+'> 禁用</label></div></div>'+
'</div>'+
'<div class="form-group" style="margin-top:14px"><label>选择内容 <span class="required">*</span></label>'+selBox+'</div>'+
'<div class="form-group" style="margin-top:14px"><label>内容说明</label><textarea id="paramDesc" rows="3" placeholder="对该'+typeLabel+'的补充描述" style="width:100%">'+desc+'</textarea></div>';
const m=document.createElement('div');
m.className='news-confirm-modal';
m.innerHTML='<div class="news-confirm-box" style="max-width:680px;width:100%;max-height:90vh;display:flex;flex-direction:column;overflow:hidden">'+
'<div style="padding:14px 20px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center"><span style="font-size:16px;font-weight:700">'+(isEdit?'编辑':'添加')+typeLabel+'</span><span style="cursor:pointer;color:#94a3b8;font-size:20px" onclick="this.closest(\'.news-confirm-modal\').remove()">×</span></div>'+
'<div id="dedupParamModal" style="padding:20px;overflow-y:auto;flex:1">'+formHtml+'</div>'+
'<div style="padding:12px 20px;border-top:1px solid var(--border);display:flex;justify-content:flex-end;gap:8px;background:#f8fafc"><button class="btn btn-ghost btn-sm" onclick="this.closest(\'.news-confirm-modal\').remove()">取消</button><button class="btn btn-primary btn-sm" onclick="dedupParamSave()">保存</button></div>'+
'</div>';
document.body.appendChild(m);
m.addEventListener('click',e=>{if(e.target===m)m.remove()});
}

function dedupParamSave(){
const modal=document.getElementById('dedupParamModal');if(!modal)return;
const isCondition=dedupParamState.formType==='condition';
const isEdit=dedupParamState.editingId!==null;
const typeLabel=isCondition?'查重条件':'字段组合';
const logicEl=modal.querySelector('input[name="paramLogic"]:checked');
if(!logicEl){toast('请选择逻辑类型','error');return}
const statusEl=modal.querySelector('input[name="paramStatus"]:checked');
const checks=modal.querySelectorAll('.param-sel-check:checked');
if(checks.length===0){toast(isCondition?'请至少选择一个字段组合':'请至少选择一个字段','error');return}
if(!isCondition){
const name=modal.querySelector('#paramName').value.trim();
if(!name){toast('请输入组合名称','error');return}
}
toast((isEdit?'更新':'添加')+typeLabel+'成功');
m_remove(modal);
renderPage('quality-dup-param')
}
function m_remove(el){const m=el.closest('.news-confirm-modal');if(m)m.remove()}

